-- Demo data for the whole system, built around the students in
-- prisma/demo-data/high_school_students.csv.
--
-- GENERATED by scripts/generate-demo-data.mjs from prisma/demo-data/populate.sql
-- and the CSV. Edit those and regenerate; do not edit the migration by hand.
--
-- Runs once per database (Prisma records it). Everything is linked to the
-- users that already exist: the school with the most users, and its ADMIN,
-- HEAD, BURSAR, DIRECTOR, LIBRARIAN and TEACHER accounts (another user stands
-- in where a role is missing). With no users at all it does nothing.
--
-- It starts by emptying every table except users and logins, so the school
-- holds only this demo data afterwards.
--
-- Calendar: academic year 2026; Terms 1 and 2 closed, Term 3 open
-- (8 Sep – 4 Dec). Payments, marks and requests are dated up to 13 Oct 2026.

-- Deterministic pseudo-random number in [0, 1) for a text key, so the data is
-- the same on every database.
CREATE OR REPLACE FUNCTION demo_rand(k TEXT) RETURNS DOUBLE PRECISION
LANGUAGE SQL IMMUTABLE AS $$
  SELECT ((('x' || substr(md5(k), 1, 8))::bit(32)::int)::bigint + 2147483648) / 4294967296.0
$$;

-- ZIMSEC O-Level grades.
CREATE OR REPLACE FUNCTION demo_grade(p NUMERIC) RETURNS TEXT
LANGUAGE SQL IMMUTABLE AS $$
  SELECT CASE WHEN p >= 75 THEN 'A' WHEN p >= 65 THEN 'B' WHEN p >= 50 THEN 'C'
              WHEN p >= 40 THEN 'D' WHEN p >= 30 THEN 'E' ELSE 'U' END
$$;

CREATE TEMP TABLE demo_csv (
  adm               TEXT PRIMARY KEY,
  first_name        TEXT NOT NULL,
  surname           TEXT NOT NULL,
  gender            TEXT NOT NULL,
  dob               DATE NOT NULL,
  form              INT  NOT NULL,
  stream            TEXT NOT NULL,
  class_name        TEXT NOT NULL,
  enrollment_year   INT  NOT NULL,
  guardian_name     TEXT NOT NULL,
  relationship      TEXT NOT NULL,
  relationship_note TEXT,
  guardian_phone    TEXT NOT NULL,
  house_number      TEXT,
  suburb            TEXT,
  city              TEXT,
  address           TEXT,
  status            TEXT NOT NULL
);

