  VALUES ('demo-disposal-old-bus', sid, 'demo-asset-old-bus', DATE '2026-03-18', 'Beyond economic repair', 'SOLD',    2500, 'USD', admin_id, TIMESTAMP '2026-03-18 12:00'),
