  -- ── Library ────────────────────────────────────────────────────────────────
  INSERT INTO "Book" (id, "schoolId", isbn, title, author, subject, publisher, year, "shelfLocation", "totalCopies")
  SELECT 'demo-book-' || b.n, sid, b.isbn, b.title, b.author, b.subject, b.publisher, b.year, b.shelf, b.copies
