      (11, '9780582055420', 'Principles of Accounts',              'F. Wood',         'Accounts',         'Longman',            2003, 'A1',  3),
      (12, NULL,            'Heritage Studies, Form 1',            'Curriculum Development Unit', 'Heritage', 'CDU',           2017, 'HS1', 4),
